package com.bitewise.controller;
import com.bitewise.dto.ExpenseDtos.*; import com.bitewise.service.ExpenseService; import jakarta.validation.Valid; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/expenses") public class ExpenseController {private final ExpenseService s; public ExpenseController(ExpenseService s){this.s=s;} @GetMapping public List<ExpenseResponse> list(@RequestParam LocalDate from,@RequestParam LocalDate to){return s.list(from,to);} @PostMapping public ExpenseResponse add(@Valid @RequestBody ExpenseRequest r){return s.add(r);} @GetMapping("/categories") public List<CategoryResponse> categories(){return s.categories();} @PostMapping("/categories") public CategoryResponse addCategory(@Valid @RequestBody CategoryRequest r){return s.addCategory(r);} }
